"""Natural bilingual report prose; exact engineering literals stay in the appendix."""
import html,json
from common_v1 import PREFIX
def bi(zh,en):return '<span class="r14-zh" lang="zh">'+html.escape(zh)+'</span><span class="r14-en" lang="en">'+html.escape(en)+'</span>'
def para(zh,en):return '<p>'+bi(zh,en)+'</p>'
def title(zh,en):return '<h3>'+bi(zh,en)+'</h3>'
STYLE='''
#nativeAttemptIncrement14{scroll-margin-top:1rem;border-top:3px solid #287b8e;padding-top:1rem}
.r14-controls{display:flex;flex-wrap:wrap;gap:1rem;margin:1rem 0;border:1px solid #ccd4d4;padding:.75rem}
.r14-en{display:none}#nativeAttemptIncrement14:has(#r14LanguageEN:checked) .r14-en{display:inline}
#nativeAttemptIncrement14:has(#r14LanguageEN:checked) .r14-zh{display:none}
#nativeAttemptIncrement14:has(#r14Summary:checked) .r14-detail{display:none}
.r14-cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:.7rem;margin:1rem 0}
.r14-cards>div{background:#f1f5f4;border:1px solid #ccd4d4;padding:.8rem}.r14-cards strong{display:block;font-size:1.3rem}
.r14-gallery{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem}.r14-gallery figure{margin:0}
#nativeAttemptIncrement14 figure img{display:block;width:100%;height:auto;max-width:1100px}
#nativeAttemptIncrement14 figure{margin:1.1rem 0}#nativeAttemptIncrement14 figcaption{font-size:.9rem;line-height:1.6;margin-top:.5rem}
#nativeAttemptIncrement14 table{min-width:620px;width:100%;border-collapse:collapse}#nativeAttemptIncrement14 th,#nativeAttemptIncrement14 td{padding:.7rem;border-bottom:1px solid #d2d8d8;text-align:left;vertical-align:top}
#nativeAttemptIncrement14 pre{white-space:pre-wrap;overflow-wrap:anywhere;max-width:100%}
#nativeAttemptIncrement14 .table-window{max-width:100%;overflow:auto}#nativeAttemptIncrement14 details{border:1px solid #cdd5d5;padding:.8rem;margin:1rem 0}
@media(max-width:650px){.r14-gallery{grid-template-columns:1fr}#nativeAttemptIncrement14{overflow-wrap:anywhere}.r14-controls{gap:.6rem}.r14-cards{grid-template-columns:repeat(2,minmax(0,1fr))}}
'''
def render(f):
    s='<section id="nativeAttemptIncrement14"><h2>'+bi('报告14：初始覆盖已验收，首步与完整安全仍未通过','REPORT14: initial coverage verified; first-step and full safety requirements remain unmet')+'</h2>'
    s+='<fieldset class="r14-controls"><legend>阅读模式 / Reading controls</legend><label><input type="radio" id="r14LanguageZH" name="r14lang" checked>中文</label><label><input type="radio" id="r14LanguageEN" name="r14lang">English</label><label><input type="radio" id="r14Detailed" name="r14detail" checked>详细 / Detailed</label><label><input type="radio" id="r14Summary" name="r14detail">摘要 / Summary</label></fieldset><div class="r14-content">'
    s+='<p id="r14FrozenTime">'+bi('固定科学快照，非实时状态','Fixed scientific snapshot, not live status')+'：<time datetime="'+f['snapshot_utc']+'">'+f['snapshot_utc']+'</time> / Asia/Shanghai '+f['snapshot_Asia_Shanghai']+'</p>'
    s+=para('本轮第一次有独立数据验收支持全部32个初始相机组。每组包含四臂各三个手部视角及三个宽视角，共480张选定原图。这个进展解决了本轮初态的规定像素覆盖，尚未完成后续12步挑战或最终相机验收，安全银行仍为0。','Independent data checks now support all32 initial camera groups: three hand views per arm for four arms, plus three wide views per group, totaling480 selected original images. This establishes the prescribed initial pixel coverage for this attempt. It does not complete the12-step challenge or final camera checks; the safety bank remains0.')
    s+='<div class="r14-cards" id="r14AcceptanceIndicators">'
    for z,e,v in [('模型预测','Model predictions','40,960 MODEL_ONLY'),('初始相机','Initial camera','32 / 32'),('完整挑战','Complete challenge','0 / 32'),('安全银行','Safety bank','0'),('任务 / 留出集','Tasks / holdout','NOT_RUN / UNOPENED')]:s+='<div>'+bi(z,e)+'<strong>'+v+'</strong></div>'
    s+='</div>'+para('首个已记录挑战步中，32个候选均触发至少一个原数值门槛。两条lane的球代理最小间距由正转负，另有位置与速度门槛触发。接触标量虽然可以从保存的点记录复算，但“新鲜”标签尚无独立SDK刷新时刻证据，因此不能把这些数值拒绝提升为完整物理判定。','At the first recorded challenge step, all32 candidates triggered at least one original numerical predicate. Two lanes changed from positive to negative minimum sphere-proxy gaps, with position and velocity predicates also triggered. Stored point records support scalar reconstruction, but the fresh label has no independent SDK refresh-epoch evidence; these numerical denials do not establish a complete physical verdict.')
    s+='<div class="r14-detail">'+title('方法与实验设置','Methods and experimental setup')
    s+=para('本轮仍是此前固定的同32个开发候选重试，保持74维原生位置、速度、目标以及原门槛。模型8192与补充32768各自保留分母，累计40960仅为模型预测；重复这32个候选和读取初态、首步，不产生64个新的独立实验样本。正式留出集未开启。','This is a related retry of the same32 fixed development candidates, with74 native position, velocity and target coordinates and unchanged thresholds. The original8192 and supplemental32768 model cohorts retain separate denominators; their total40960 is model prediction only. Repeating32 candidates and reading initial and first-step states does not create64 new independent experiments. The formal holdout remains unopened.')
    s+=para('独立审计分四个8候选CPU分片消费既有闭合数据，核验初始相机、74维数值、9021个几何代理与82个接触标量身份及记录运算。本报告只消费该审计的闭合JSON和64行CSV，并按SHA复制选定原图；没有重新执行原生物理、SDK或整批原始数组复算。','The independent audit consumed closed data in four CPU shards of8 candidates, checking initial cameras,74-coordinate numerical fields,9021 geometry proxies and identities and recorded operations for82 contact scalars. This report consumes its closed JSON and64-row CSV and copies selected original images bySHA. It performs no native physics, SDK execution or full raw-array re-audit.')
    s+=para('相机门槛保持原定义：每臂三个相隔至少30°的视角；掌部至少2048像素，五指各至少512，每个原生手部body至少64且无缺口。三个宽视角中，四臂与两桌各在至少一幅达到1024像素，关键前臂与wrist2 body各达到128。每次渲染保持原27项状态，整批32候选均核验；这些可见像素门槛不等于全表面、无遮挡或接触面认证。','The original camera definition remains: three views per arm separated by at least30°; palm at least2048 pixels, each of five fingers at least512, and every native hand body at least64 without gaps. Across the three wide views, each of four arms and two tables reaches1024 pixels in at least one view, and each critical forearm and wrist2 body reaches128. The original27 held-state fields are checked across all32 candidates for every render. These visible-pixel thresholds do not certify complete surfaces, absence of occlusion or contact patches.')
    s+=title('结果：把初态、首步和完整轨迹分开','Results: initial state, first step and complete trajectory')
    s+='<div class="table-window"><table id="r14ScopeTable"><thead><tr><th>'+bi('范围','Scope')+'</th><th>'+bi('实际证据','Actual evidence')+'</th><th>'+bi('可以得出的结论','Supported conclusion')+'</th></tr></thead><tbody>'
    rows=[('初始相机','Initial camera','32/32组；480选定原图；1201初始attempt图像独立审计。','32/32 groups;480 selected originals;1201 initial-attempt images independently audited.','仅本轮初始规定覆盖通过；不补足最终相机。','Prescribed initial coverage passes for this attempt only; final cameras remain missing.'),('保存的图像','Saved images','共1312张；另111张部分或孤立图像保留。','1312 total;111 other partial or orphan images retained.','111张未获得像素验收，不能计入480或合格组。','The111 are not pixel-accepted and do not enlarge the480 selected images or qualified groups.'),('已提交数值','Committed numerical fields','初态micro0与首步micro1，各32条相关观察。','Initial micro0 and first-step micro1, each32 related observations.','首步32/32记录数值拒绝；不是完整物理安全结论。','First-step recorded numerical denial32/32; not a complete physical safety verdict.'),('完整12步','Complete12 steps','micro2..12与最终相机缺失；producer终结收据缺失。','micro2..12 and final cameras missing; producer final receipt absent.','完整挑战未完成；不能从两行补造推进总数。','Full challenge incomplete; two rows cannot synthesize the total physical advance count.')]
    for z,e,a,b,c,d in rows:s+='<tr><th>'+bi(z,e)+'</th><td>'+bi(a,b)+'</td><td>'+bi(c,d)+'</td></tr>'
    s+='</tbody></table></div><figure id="r14All32"><a href="'+PREFIX+'/figures/all32_initial_to_micro1.svg"><img src="'+PREFIX+'/figures/all32_initial_to_micro1.png" alt="All32 lanes: initial and first-step sphere-proxy gaps, velocity ratios and recorded predicate flags"></a><figcaption>'+bi('全部32个相关候选，初态到首步。间距为球代理最小值，速度比为74维最大|qd|/原生vmax；下方拒绝标记会重叠，不能相加成样本数。接触标量一行只表示记录运算门槛，新鲜性仍未知。','All32 related candidates, initial to first step. Gaps are sphere-proxy minima; velocity ratios are the74-coordinate maximum|qd|/native vmax. Predicate flags overlap and must not be summed as samples. The contact-scalar row is a recorded-operation threshold; freshness remains unknown.')+'</figcaption></figure>'
    s+=para('首步门槛触发数量为：硬位置18、速度22、软范围3、球代理负间距2、接触标量30；非有限值和目标保持各0。它们相互重叠。保存的代理距离与独立float64复算最大差约1.166微米、符号分歧0，仅说明这64条相关记录的代理运算一致，不构成网格碰撞或全局误差界证明。','First-step predicate counts are18 hard-position,22 velocity,3 soft-range,2 negative proxy-gap and30 contact-scalar, with0 nonfinite and0 held-target flags. Counts overlap. Stored proxy distances agree with independent float64 reconstruction to about1.166 micrometers with0 sign disagreements. This establishes proxy-operation agreement on64 related records, not mesh-collision certification or a global error bound.')
    s+='<figure id="r14Witnesses"><a href="'+PREFIX+'/figures/two_lanes_first_step.svg"><img src="'+PREFIX+'/figures/two_lanes_first_step.png" alt="Lane17 and lane27 minimum proxy gap and native velocity ratio before and after first recorded step"></a><figcaption>'+bi('按首步负代理间距这一明确诊断条件展示两条lane，不是安全挑选。lane17：+0.922→−8.542毫米；lane27：+1.088→−4.360毫米，首步最大速度比1.535。图为数值记录，下面照片均为初始相机，不存在已验收的首步后照片。','Two lanes are shown under the explicit diagnostic criterion of a negative first-step proxy gap, not selected for safety. Lane17:+0.922 to−8.542mm; lane27:+1.088 to−4.360mm, with first-step maximum velocity ratio1.535. The plot shows numerical records; images below are initial cameras, not accepted post-step photographs.')+'</figcaption></figure>'
    s+=title('真实初始画面与全量选定原图','Actual initial views and all selected originals')+para('以下展示两条负间距lane的初始宽视角和手部视角，原始1280×720字节不编辑、不裁切。该初始相机组已通过规定的独立像素覆盖；画面仍可能包含同环境其他手或遮挡，不能称为无异物、无接触或安全。详细页保留所有32组，每组15幅选定原图及身份、SHA与审计范围。','Initial wide and hand views for the two negative-gap lanes appear below as unchanged, uncropped1280×720 originals. Their initial groups pass the prescribed independent pixel coverage. Images may still contain other hands in the same environment or occlusion; they are not evidence of foreign-free, contact-free or safe scenes. Detail pages retain all32 groups,15 selected originals each, with identities, SHA and audit scope.')
    s+='<div class="r14-gallery">'
    for e in f['previews']:
        s+='<figure><a href="'+PREFIX+'/gallery/env_'+str(e['lane']).zfill(3)+'.html"><img loading="lazy" src="'+PREFIX+'/'+e['relative']+'" alt="Original initial lane'+str(e['lane'])+' '+e['role']+' view"></a><figcaption>'+bi('lane'+str(e['lane'])+' / '+e['role']+'：初始组覆盖已审计，完整挑战未通过。','lane'+str(e['lane'])+' / '+e['role']+': initial group coverage audited; full challenge not accepted.')+'</figcaption></figure>'
    s+='</div><p><a id="r14FullGallery" href="'+PREFIX+'/gallery/index.html">'+bi('查看全部32组 × 15张选定原图（480张）','View all32 groups ×15 selected originals (480 images)')+'</a></p>'
    s+=title('失败分析','Failure analysis')+para('静态模型使用初始位置预测代理间距，而原生初始速度并不为零，保持的位置目标等于初始位置。两条lane的记录说明：初始代理间距为正不能保证下一步仍满足约束。驱动、被动约束、接触以及未恢复的求解器状态各自的贡献尚未被因果实验区分，不能只从大标量或一次超时选定根因。','The static model predicts proxy gaps from initial positions, while native initial velocities are nonzero and held position targets equal initial positions. The two recorded lanes show that positive initial proxy gaps do not ensure next-step compliance. Contributions from drives, passive constraints, contacts and unrestored solver state have not been separated by a causal experiment; large scalars or a timeout alone do not identify a root cause.')
    s+=para('采集在原1200秒期限附近被关闭，未留下完整producer终结记录。监督器也记录了期限附近一次GPU查询超时；这不证明资源不足、GPU选择错误或此前崩溃已修复。与历史重试相比，本轮初始图像和提交行覆盖增加，是数据完整性进展，不能据此宣称提速、稳定性或安全成功。','Capture closed near the original1200-second deadline without a complete producer final record. The supervisor also recorded a near-deadline GPU-query timeout. This does not establish resource shortage, wrong GPU selection or repair of the earlier crash. Compared with historical related retries, initial-image and committed-row coverage increased; that is progress in data completeness, not proof of speed, stability or safety gains.')
    s+=title('限制与验收表','Limitations and acceptance table')+para('接触刷新时刻、实际驱动峰值、微步内力峰、力矩坐标、终端集合与全局误差界仍未知。初始点标签为“不新鲜”，首步“新鲜”标签也不能替代独立SDK刷新证据；既不能把初始接触读数判作全32失败，也不能判作安全通过。原27项保持要求有效；42项仍是未绑定、未采纳提案。','Contact refresh epochs, actual drive peaks, within-micro force peaks, wrench coordinates, terminal sets and a global error bound remain unknown. Initial points are labeled not fresh, and the first-step fresh label does not replace independent SDK refresh evidence. Initial readings establish neither contact failure for all32 nor safety acceptance. The original27 held-state requirements remain;42 fields are an unbound, unadopted proposal.')
    s+='<div class="table-window"><table id="r14EvidenceTable"><thead><tr><th>'+bi('要求','Requirement')+'</th><th>'+bi('实际达到的范围','Achieved scope')+'</th><th>'+bi('验收缺口','Acceptance gap')+'</th></tr></thead><tbody>'
    rows=[('模型预测','Model prediction','8192与32768分别完成；40960 MODEL_ONLY。','8192 and32768 separately completed;40960 MODEL_ONLY.','956个预测CLEAR不等于安全样本；原8192空调度不变。','956 predicted CLEAR labels are not safe samples; original8192 empty schedule retained.'),('初始/最终强相机','Initial/final strong camera','初始32/32，480选定原图与原27项保持核验。','Initial32/32,480 selected originals and original27 held fields checked.','最终相机缺失；不证明全网格/无遮挡。','Final cameras missing; no complete-mesh or occlusion-free proof.'),('全74维/12微步','All74 coordinates/12 microsteps','micro0,1共64条相关观察；首步数值拒绝32/32。','64 related observations at micro0,1; first-step numerical denial32/32.','micro2..12缺失；原门槛不放宽。','micro2..12 missing; original thresholds unchanged.'),('接触/驱动/误差界','Contact/drive/error bound','保存点身份与标量运算复算，代理运算一致。','Stored point identity/scalar reconstruction and proxy-operation agreement.','刷新时刻、驱动峰值与全局界未知；物理安全未通过。','Refresh epoch, drive peaks and global bound unknown; physical safety not accepted.'),('任务/留出/安全银行','Tasks/holdout/safety bank','任务未运行；留出集未开启；银行0。','Tasks not run; holdout unopened; bank0.','完整要求未达成，初始覆盖与模型预测不能替代。','Full requirements unmet; initial coverage and model prediction do not replace them.')]
    for z,e,a,b,c,d in rows:s+='<tr><th>'+bi(z,e)+'</th><td>'+bi(a,b)+'</td><td>'+bi(c,d)+'</td></tr>'
    s+='</tbody></table></div>'+title('下一项可检验的工作','Next testable work')+para('先补足完整挑战与最终状态证据，并针对非零初始速度、保持目标下的驱动与被动反力做独立、预先冻结的区分实验；刷新时刻与实际峰值测量仍需权威接口。新实验未执行，不能用本轮有限记录推断其结果，也不改变原采样分母或门槛。','Complete the challenge and final-state evidence, and use an independently frozen experiment to separate drive and passive reactions under nonzero initial velocity and held targets. Refresh epochs and actual peaks still require authoritative measurement interfaces. These new experiments have not run; the finite records here predict neither their outcomes nor changes to the original denominators or thresholds.')
    s+='</div><details id="r14EvidenceAppendix"><summary>'+bi('证据与复现附录：原始字段、退出状态、SHA、CSV与原图清单','Evidence and reproduction appendix: exact fields, exits, SHA, CSV and original-image inventory')+'</summary><pre>'+html.escape(json.dumps({k:f[k] for k in ['snapshot_utc','native_terminal','independent_data_scope','physical_unknowns','source_refs']},ensure_ascii=False,indent=2))+'</pre><ul>'
    for k in f['source_refs']:s+='<li><a href="'+PREFIX+'/evidence/'+k+'.json">'+html.escape(k)+'</a></li>'
    for path,label in [('COMMITTED_2X32_NUMERIC_V1.csv','64-row closed CSV'),('SELECTED_ORIGINAL_IMAGE_INVENTORY_V1.json','480 original image SHA/source inventory'),('FACTS_INCREMENT14_V1.json','Typed frozen facts'),('source/figures_v1.py','Recomputable plot code'),('archive_report13/index.html','Original-byte historical Report13')]:s+='<li><a href="'+PREFIX+'/'+path+'" download>'+label+'</a></li>'
    s+='</ul></details></div></section>';return s
def gallery_page(group):
    lane=group['lane'];s='<!doctype html><html lang="zh"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>V10 initial lane'+str(lane)+'</title><style>body{max-width:1000px;margin:2rem auto;padding:0 1rem;font:16px/1.65 system-ui;color:#203239}figure{margin:1.5rem 0}img{width:100%;height:auto}figcaption{overflow-wrap:anywhere}body{overflow-wrap:anywhere}pre{white-space:pre-wrap;overflow-wrap:anywhere}a{color:#287b8e}</style><body><a href="index.html">全部32组 / All32 groups</a><h1>V10 initial lane'+str(lane)+'</h1><p>规定初始像素覆盖已通过独立数据验收，完整12步与物理安全未通过。Prescribed initial pixel coverage passes the independent DATA audit; full12-step and physical acceptance remain incomplete. Original1280×720; no edits/crop. Every image below is INITIAL, not micro1/final.</p><pre>'+html.escape(json.dumps(group['candidate'],ensure_ascii=False))+'</pre>'
    for e in group['images']:s+='<figure><a href="../'+e['relative']+'"><img loading="lazy" src="../'+e['relative']+'" alt="Initial lane'+str(lane)+' '+e['role']+' view'+str(e['view'])+'"></a><figcaption>'+html.escape(e['role']+' selected view'+str(e['view'])+' · INITIAL_ONLY · '+e['sha256'])+'</figcaption></figure>'
    s+='<details><summary>独立覆盖摘要 / Independent coverage summary</summary><pre>'+html.escape(json.dumps(group['coverage'],ensure_ascii=False,indent=2))+'</pre></details></body></html>';return s
